import{VERSION,clamp,money,esc,today,dayShift,daysBetween,demo,metrics,salesFor,quality,candidates,recommendations,campaign,approve,validateDataset,productCSV,parseProductCSV}from'./core.mjs';
import{PROFILES,demoProfile}from'./profiles.mjs';
import{renderAnalytics,renderForecast,renderLab,simulate,metricHelp}from'./insights.mjs';
import{TASKS,llmStatus,loadLLM,askLLM,stopLLM,answerWarnings,renderAssistant,chatBubble}from'./llm-client.mjs';
const KEY='rostok-mvp-v1',root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const initial=()=>({data:demoProfile('dairy'),profile:'dairy',events:[],goal:'balanced',budget:60,compact:false,onboarded:false});
let insightDays=28,forecastProduct=null,forecastHorizon=7,forecastMethod='weekday',chat=[],accounts={};
try{accounts=JSON.parse(localStorage.getItem('rostok-accounts-v1')||'{}');}catch{}
let state=initial(),page='today',query='',filter='all',period=7,activeAction=null,importDraft=null,storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw){state={...initial(),...raw,data:validateDataset(raw.data),events:Array.isArray(raw.events)?raw.events.slice(0,500):[]};}}catch{state=initial();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;toast('Не удалось сохранить. Скачайте данные, прежде чем закрыть вкладку.');}}
const I={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',leaf:'<path d="M20 3C8 2 2 9 5 16c7 5 15-1 15-13Z"/><path d="M4 21 15 10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 6-8"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',tag:'<path d="m3 3 9 1 9 9-8 8-9-9-1-9Z"/><circle cx="8" cy="8" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="m6 15 6-6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',plus:'<path d="M12 4v16M4 12h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9 9-4M3 8l9 4m0 0v10M8 5l9 5"/>',undo:'<path d="M4 4v6h6M4 10c3-8 15-6 16 2s-8 12-13 7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>'};
const icon=(name,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[name]||I.leaf}</svg>`;
const btn=(text,action,cls='secondary',extra='')=>`<button class="btn ${cls}" data-act="${action}" ${extra}>${text}</button>`;
const badge=(text,cl='')=>`<span class="badge ${cl}">${text}</span>`;
const tip=text=>`<button class="tip" type="button" aria-label="${esc(text)}" data-tooltip="${esc(text)}">${icon('info')}</button>`;
const pct=v=>(v*100).toFixed(1).replace('.',',')+'%';
const dateLong=d=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',weekday:'long',timeZone:'Europe/Moscow'}).format(new Date(d+'T12:00:00Z'));
const nav=[['today','sun','Сегодня'],['assistant','spark','ИИ-помощник'],['analytics','chart','Аналитика +'],['forecast','chart','Прогноз спроса'],['products','grid','Ассортимент'],['sales','chart','Продажи'],['clients','people','Покупатели'],['campaigns','tag','Акции и наборы'],['lab','spark','А что, если?'],['history','clock','План и история'],['data','data','Данные и правила']];
function shell(){const done=state.events.filter(e=>e.day===today()&&e.status==='approved').length;root.innerHTML=`<aside class="sidebar"><a class="brand" href="#today" aria-label="Росток, сегодня"><img src="./favicon.svg" alt="" width="38" height="38"><span>росток<span class="brand-caption">ПОМОЩНИК ВАШЕЙ ФЕРМЫ</span></span></a><button class="workspace" data-act="accounts"><span class="farmmark">${PROFILES.find(p=>p.id===state.profile)?.initials||'Ф'}</span><div><b>${esc(state.data.farm)}</b><span>Сменить демо-хозяйство ↗</span></div></button><nav aria-label="Основная навигация">${nav.map(([id,ic,label])=>`<button class="nav-item ${page===id?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='today'?'<small>'+recommendations(state.data,state).length+'</small>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="quiet" data-act="onboarding">${icon('info')} Как это работает</button><div class="local-note">${icon('shield')}<p>Решаете только вы<span>Ничего не меняем и не отправляем без подтверждения</span></p></div><div class="rshb">РСХБ<span>.цифра</span><small>КОНЦЕПТ ПРОДУКТА</small></div></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-menu icon-btn" aria-label="Открыть меню" data-act="menu">${icon('menu')}</button><div class="crumb">Моя ферма <span>/</span> ${nav.find(x=>x[0]===page)?.[2]||'Сегодня'}</div><button class="global-search" data-act="search">${icon('search')} Найти товар или действие <kbd>⌘ K</kbd></button><button class="demo-chip" data-act="scenario"><span></span> ${state.data.demo?'Демо-данные':'Ваши данные'}</button><button class="avatar" data-act="settings" aria-label="Настройки фермы">СБ</button></header><main id="main" tabindex="-1" class="page enter ${page==='today'?'today-view':''}">${renderPage()}</main><footer class="footer"><span>Росток · MVP 1.1 <i>•</i> ${esc(state.data.source)}</span><button data-act="rules">Как рассчитаны рекомендации ${icon('arrow')}</button></footer></div>`;document.title=`Росток · ${nav.find(x=>x[0]===page)?.[2]||'Сегодня'}`;if(!storageOK)toast('Хранилище браузера недоступно. Экспортируйте изменения.');}
function title(eyebrow,h,desc,actions=''){return`<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${h}</h1><p class="subhead">${desc}</p></div><div class="heading-actions">${actions}</div></section>`;}
function renderPage(){return({analytics:()=>renderAnalytics(state.data,insightDays),forecast:()=>renderForecast(state.data,forecastProduct,forecastHorizon,forecastMethod),assistant:()=>renderAssistant(state.data,chat),lab:()=>renderLab(state.data),today:todayPage,products:productsPage,sales:salesPage,clients:clientsPage,campaigns:campaignsPage,history:historyPage,data:dataPage}[page]||todayPage)();}
function sparkChart(days=7){const vals=Array.from({length:days},(_,i)=>{const day=dayShift(state.data.asOf,i-days+1);return{day,value:state.data.sales.filter(s=>s.date===day).reduce((a,x)=>a+x.revenue,0)};});const max=Math.max(1,...vals.map(x=>x.value))*1.18,w=820,h=180;const pts=vals.map((x,i)=>[40+i*(w-60)/(days-1),h-x.value/max*(h-25)]);const points=pts.map(p=>p.join(',')).join(' ');return`<div class="chart-wrap"><svg viewBox="0 0 840 220" role="img" aria-label="Выручка по дням за ${days} дней: ${vals.map(x=>`${x.day}: ${money(x.value)}`).join('; ')}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8eaa71" stop-opacity=".32"/><stop offset="1" stop-color="#8eaa71" stop-opacity="0"/></linearGradient></defs>${[45,90,135,180].map(y=>`<line x1="40" y1="${y}" x2="800" y2="${y}" stroke="#e8ece2" stroke-dasharray="4 6"/>`).join('')}<polygon points="40,185 ${points} 800,185" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#426347" stroke-width="3.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#426347"><title>${vals[i].day}: ${money(vals[i].value)}</title></circle>`).join('')}${vals.filter((_,i)=>days===7||i%4===0||i===days-1).map(x=>`<text x="${pts[vals.indexOf(x)][0]}" y="213" text-anchor="middle" fill="#7e897e" font-size="13">${x.day.slice(8)}.${x.day.slice(5,7)}</text>`).join('')}</svg></div>`;}
function actionCard(a,i){const typeIcon={waste:'leaf',stock:'box',card:'grid',retention:'people',data:'data'}[a.type];return`<article class="action-card ${i===0?'featured':''}"><div class="action-top"><span class="action-num">0${i+1}</span>${badge(i===0?'Сначала это':a.short,i===0?'light':'soft')}</div><div class="action-symbol">${icon(typeIcon)}</div><h3>${esc(a.title)}</h3><p class="reason">${esc(a.reason)}</p><div class="action-value"><span>${a.label} ${tip('Сценарный диапазон, а не гарантия. Откройте действие, чтобы увидеть формулу и допущения.')}</span><strong>${money(a.low)} <small>–</small> ${money(a.high)}</strong><small>${a.horizon} дн. · ${esc(a.effectUnits)}</small></div><div class="action-meta"><span>${icon('clock')} ${a.effort} мин</span><span>Приоритет ${a.score}/100</span></div><button class="btn ${i===0?'cream':'secondary'} full" data-action="${a.id}">Разобрать действие ${icon('arrow')}</button></article>`;}
function todayPage(){const data=state.data,all=candidates(data,{goal:state.goal}),available=recommendations(data,state,999),recs=available.slice(0,3),m=metrics(data,null,7),q=quality(data),done=state.events.filter(e=>e.day===today()&&['approved','done'].includes(e.status)).length;return`${title(dateLong(today()),'Три приоритета <em>на сегодня.</em>','Проверьте причины и расчёты. Выберите, что делать дальше.',btn(icon('down')+' Отчёт за неделю','report'))}<section class="morning-note"><div class="morning-icon">${icon('sun')}</div><p><b>Сегодня не нужно успеть всё.</b><span>${recs.length?`${recs.length} приоритетных действия займут около ${recs.reduce((s,a)=>s+a.effort,0)} минут. Остальное может подождать.`:'Все приоритеты на сегодня рассмотрены. Можно вернуться к плану или посмотреть другие сигналы.'}</span></p><button data-act="rules">Почему эти действия? ${icon('arrow')}</button></section><section class="stats-strip" aria-label="Показатели за неделю"><div><span>Выручка за 7 дней ${tip('Сумма revenue из строк продаж. Учебные данные не отражают реальную ферму.')}</span><strong>${money(m.revenue)}</strong><small>По загруженным продажам</small></div><div><span>Валовая маржа ${tip('Выручка минус количество × текущая себестоимость товара. Не учитывает доставку, налоги и прочие расходы.')}</span><strong>${money(m.margin)}</strong><small>До прочих расходов</small></div><div><span>Товаров в ассортименте</span><strong>${data.products.length}<small> позиций</small></strong><button data-nav="products">Посмотреть ассортимент ${icon('arrow')}</button></div><div><span>План на сегодня</span><strong>${done}<small> подтверждено</small></strong><button data-nav="history">Открыть план ${icon('arrow')}</button></div></section><section><div class="section-head"><div><p class="eyebrow">МЕНЬШЕ ШУМА, БОЛЬШЕ ДЕЛА</p><h2>Начните с этого <span class="counter">${recs.length}</span></h2></div><label class="select-label">Ваш фокус<select id="goal"><option value="balanced" ${state.goal==='balanced'?'selected':''}>Сбалансированный рост</option><option value="waste" ${state.goal==='waste'?'selected':''}>Сократить потери</option><option value="growth" ${state.goal==='growth'?'selected':''}>Увеличить продажи</option></select></label></div><div class="actions-grid">${recs.map(actionCard).join('')||`<div class="empty wide">${icon('check')}<h3>На сегодня всё рассмотрено</h3><p>Подтверждённые действия находятся в плане. Завершение можно отметить вручную.</p>${btn('Перейти к плану','plan')}</div>`}</div><p class="fine-print">${icon('info')} Денежные диапазоны основаны на допущениях. Их нельзя складывать: эффекты могут пересекаться. Все изменения требуют вашего решения.</p></section><section class="bottom-grid"><article class="panel"><div class="panel-head"><div><p class="eyebrow">ПУЛЬС ФЕРМЫ</p><h2>Как прошла неделя</h2></div><button class="text-button" data-nav="sales">Все продажи ${icon('arrow')}</button></div><div class="chart-summary"><strong>${m.units}</strong><span>единиц товара продано за 7 дней</span></div>${sparkChart(7)}</article><article class="panel garden-panel"><div class="panel-head"><div><p class="eyebrow">ОПИРАЕМСЯ НА ДАННЫЕ</p><h2>Что ещё заметили</h2></div>${badge(all.length+' сигналов','soft')}</div>${available.slice(3,6).map(a=>`<button class="signal-row" data-action="${a.id}"><span class="mini-icon">${icon({waste:'leaf',stock:'box',card:'grid',retention:'people',data:'data'}[a.type])}</span><span><b>${esc(a.short)}</b><small>${esc(a.title)}</small></span>${icon('arrow')}</button>`).join('')||'<p>Новых сигналов пока нет.</p>'}<button class="data-quality" data-nav="data"><span class="status-dot"></span> Полнота данных ${q.score}% <span>${q.issues.length?'Есть замечания':'Проверить источники'}</span></button></article></section>`;}
function productStatus(p){const m=metrics(state.data,p.id);if(p.expiresIn===0&&p.stock>0)return['Проверить срок','warn'];if(p.expiresIn<=3&&p.stock>m.rate*p.expiresIn)return['Партия под риском','warn'];if(m.daysCover<p.leadDays)return['Мало запаса','warn'];if(p.completeness<80||p.photos<2)return['Доработать карточку','purple'];return['В порядке','green'];}
function productCell(p){return`<div class="product-cell"><span class="product-mark ${p.color}">${esc(p.symbol)}</span><span><b>${esc(p.name)}</b><small>${esc(p.category)}</small></span></div>`;}
function productsPage(){let products=state.data.products.filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));if(filter!=='all')products=products.filter(p=>filter==='risk'?productStatus(p)[1]==='warn':p.completeness<80||p.photos<2);return`${title('ВАШ АССОРТИМЕНТ','Каждому товару<br><em>своё внимание.</em>','Остатки, маржа и качество карточек в одном месте.',btn(icon('plus')+' Добавить товар','add-product','primary'))}<div class="toolbar"><div class="tabs" aria-label="Фильтр ассортимента">${[['all','Все товары'],['risk','Требуют внимания'],['cards','Слабые карточки']].map(([id,t])=>`<button data-filter="${id}" class="${filter===id?'selected':''}">${t}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="catalog-search" placeholder="Название товара" value="${esc(query)}" aria-label="Поиск товара"></label>${btn('Экспорт CSV','export-csv')}</div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Товар</th><th>Цена / маржа</th><th>Остаток</th><th>Срок партии</th><th>Карточка</th><th>Состояние</th><th><span class="sr-only">Действия</span></th></tr></thead><tbody>${products.map(p=>{const m=metrics(state.data,p.id),status=productStatus(p);return`<tr><td>${productCell(p)}</td><td><b>${money(p.price)}</b><small>${money(p.price-p.cost)} / ${pct((p.price-p.cost)/p.price)}</small></td><td><b>${p.stock} ${esc(p.unit)}</b><small>на ${Number.isFinite(m.daysCover)?m.daysCover.toFixed(1):'∞'} дн.</small></td><td>${p.expiresIn} дн.</td><td><span>${p.completeness}%</span><div class="progress"><i style="width:${p.completeness}%"></i></div><small>${p.photos} фото</small></td><td>${badge(status[0],status[1])}</td><td><button class="icon-btn" data-edit="${p.id}" aria-label="Изменить ${esc(p.name)}">${icon('arrow')}</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">Товаров по этому запросу нет.</td></tr>'}</tbody></table></div></div><div class="callout">${icon('info')} Изменения сохраняются только в этом браузере и влияют на рекомендации. Цены и остатки на внешних площадках не меняются.</div>`;}
function salesPage(){const m=metrics(state.data,null,period),rows=state.data.products.map(p=>({p,m:metrics(state.data,p.id,period)})).sort((a,b)=>b.m.revenue-a.m.revenue);return`${title('АНАЛИТИКА БЕЗ ЛИШНЕГО','Видеть, что<br><em>приносит результат.</em>','Факты из продаж отдельно от сценарных прогнозов.',`<label class="select-label">Период<select id="period"><option value="7" ${period===7?'selected':''}>7 дней</option><option value="28" ${period===28?'selected':''}>28 дней</option></select></label>`)}<section class="stats-strip three"><div><span>Выручка</span><strong>${money(m.revenue)}</strong><small>Из строк продаж</small></div><div><span>Валовая маржа</span><strong>${money(m.margin)}</strong><small>По текущей себестоимости</small></div><div><span>Продано / просмотры</span><strong>${m.units}<small> / ${m.views}</small></strong><small>Показатель может включать повторные покупки</small></div></section><div class="panel"><div class="panel-head"><h2>Динамика выручки</h2>${badge(state.data.demo?'Учебные данные':'Импорт','soft')}</div>${sparkChart(period)}</div><section class="bottom-grid"><div class="panel"><h2>Товары по выручке</h2>${rows.map(({p,m},i)=>`<button class="revenue-row" data-edit="${p.id}"><span>${esc(p.name)}</span><div class="bar-track"><i style="width:${Math.max(1,m.revenue/(rows[0].m.revenue||1)*100)}%"></i></div><b>${money(m.revenue)}</b></button>`).join('')}</div><div class="panel"><h2>Проверьте перед выводами</h2><div class="check-note">${icon('check')} Валовая маржа не равна чистой прибыли.</div><div class="check-note">${icon('check')} Текущая себестоимость используется для всех дней периода.</div><div class="check-note">${icon('check')} Спрос прошлой недели может измениться.</div><div class="check-note">${icon('check')} Причину роста проверяем тестом, а не совпадением по времени.</div>${btn(icon('down')+' Скачать недельный отчёт','report','primary')}</div></section>`;}
function clientsPage(){const segs=state.data.segments;return`${title('ОТНОШЕНИЯ, А НЕ ПРОСТО БАЗА','Покупатели,<br><em>которые возвращаются.</em>','Только агрегированные сегменты. Без имён, телефонов и адресов.') }<div class="privacy-banner">${icon('shield')} В MVP нет персональных профилей и подключённой рассылки. Количество согласий приходит из вашей CRM в обезличенном виде.</div><div class="segments-grid">${segs.map(s=>`<article class="panel segment"><div class="segment-icon">${icon('people')}</div><h2>${esc(s.name)}</h2><div class="segment-count">${s.count}<span>покупателей</span></div><dl><div><dt>Согласились на сообщения</dt><dd>${s.consented}</dd></div><div><dt>Средний чек</dt><dd>${money(s.avgCheck)}</dd></div><div><dt>Дней с последнего заказа</dt><dd>${s.lastOrderDays}</dd></div></dl><button class="btn secondary full" data-segment="${s.id}">Подготовить сообщение ${icon('arrow')}</button></article>`).join('')||'<div class="empty">Сегменты не загружены. Импортируйте агрегированные данные.</div>'}</div><div class="panel"><div class="panel-head"><h2>Как проверить, что сообщение помогло</h2>${badge('План эксперимента','purple')}</div><div class="steps-row"><div><span>01</span><h3>Выбрать сегмент</h3><p>Только покупателей с действующим согласием. Проверка в вашей CRM.</p></div><div><span>02</span><h3>Оставить контроль</h3><p>Случайно выделить часть сегмента без сообщения. Не сравнивать разные группы.</p></div><div><span>03</span><h3>Сравнить заказы</h3><p>Смотреть разницу покупок и маржи за 7 дней. Не выдавать весь возврат за эффект.</p></div></div></div>`;}
function campaignsPage(){return`${title('ПРОДАВАТЬ ВЫГОДНО','Скидка должна<br><em>работать на вас.</em>','Сначала посчитайте маржу, затем решите, нужна ли акция.')}<div class="bottom-grid calculators"><section class="panel"><p class="eyebrow">КАЛЬКУЛЯТОР АКЦИИ</p><h2>Цена с запасом по марже</h2><label class="field">Товар<select id="promo-product">${state.data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="form-row"><label class="field">Скидка, %<input id="promo-discount" type="number" min="0" max="70" value="15"></label><label class="field">Количество<input id="promo-quantity" type="number" min="1" value="10"></label></div><div id="promo-result"></div><label class="confirm-label"><input type="checkbox" id="promo-confirm"> Я проверил цену, остаток и срок годности партии</label>${btn('Подтвердить черновик акции','save-promo','primary','id="promo-save"')}<p class="fine-print">Только локальный черновик. На сайте и площадках ничего не изменится.</p></section><section class="panel"><p class="eyebrow">КАЛЬКУЛЯТОР НАБОРА</p><h2>Объединить, а не уценить всё</h2><label class="field">Первый товар<select id="bundle-one">${state.data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="field">Второй товар<select id="bundle-two">${state.data.products.map((p,i)=>`<option value="${p.id}" ${i===3?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Цена набора, ₽<input id="bundle-price" type="number" min="1" value="540"></label><div id="bundle-result"></div><label class="confirm-label"><input type="checkbox" id="bundle-confirm"> Я проверил комплектность и цену набора</label>${btn('Подтвердить черновик набора','save-bundle','secondary','id="bundle-save"')}<p class="fine-print">Увеличение среднего чека не гарантировано. Набор не создаётся на площадках.</p></section></div><div class="callout">${icon('info')} На странице показана валовая маржа. Учтите упаковку, доставку, комиссию и другие расходы перед запуском.</div>`;}
function historyPage(){const events=state.events,active=events.filter(e=>e.status==='approved'),done=events.filter(e=>e.status==='done');return`${title('РЕШЕНИЯ ОСТАЮТСЯ У ВАС','Сначала решение.<br><em>Потом действие.</em>','Локальный журнал: что вы подтвердили, отложили и выполнили.',btn(icon('down')+' Выгрузить журнал','export-history'))}<section class="stats-strip three"><div><span>Подтверждено</span><strong>${active.length}</strong><small>Ожидают ручного выполнения</small></div><div><span>Отмечено выполненным</span><strong>${done.length}</strong><small>Самооценка, не ответ площадки</small></div><div><span>Измерение эффекта</span><strong>${events.filter(e=>Number.isFinite(e.actual)).length}</strong><small>Ручные наблюдения, не доказанный прирост</small></div></section><div class="panel history-list">${events.length?events.map(e=>`<article class="history-row"><div class="history-marker ${e.status==='done'?'green':''}">${icon(e.status==='done'?'check':'clock')}</div><div class="history-main"><div>${badge(({approved:'Подтверждено',done:'Выполнено вручную',rejected:'Не подходит',snoozed:'Отложено'})[e.status]||e.status,e.status==='done'?'green':e.status==='rejected'?'soft':'purple')}<time>${new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(e.at))}</time></div><h3>${esc(e.title)}</h3><p>${e.status==='snoozed'?'Отложено до '+esc(e.until):e.reason?esc(e.reason):'Внешние системы не изменялись. Выполнение и публикация остаются за вами.'}</p>${Number.isFinite(e.actual)?`<small>Внесённое наблюдение: ${money(e.actual)}. ${esc(e.observation||'')} Не является доказанным эффектом.</small>`:''}</div><div class="history-buttons">${e.status==='approved'?`<button class="btn secondary" data-done="${e.id}">Отметить выполнение</button>`:''}${e.status==='done'?`<button class="btn secondary" data-measure="${e.id}">Записать результат</button>`:''}${e.status!=='done'?`<button class="text-button" data-remove="${e.id}">Отменить запись</button>`:''}</div></article>`).join(''):`<div class="empty">${icon('clock')}<h2>Пока ни одного решения</h2><p>Откройте действие на главной, проверьте расчёт и подтвердите черновик.</p><button class="btn primary" data-nav="today">К приоритетам</button></div>`}</div>`;}
function dataPage(){const q=quality(state.data);return`${title('ПОНЯТНО, ОТКУДА ВЫВОДЫ','Хорошие решения<br><em>начинаются с данных.</em>','Демонстрация использует вымышленные продажи и обезличенные сегменты.',btn(icon('down')+' Скачать данные JSON','export-data'))}<div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>Текущий набор</h2>${badge(state.data.demo?'Демонстрационный':'Импортирован','soft')}</div><dl class="data-dl"><div><dt>Источник</dt><dd>${esc(state.data.source)}</dd></div><div><dt>Дата набора</dt><dd>${esc(state.data.asOf)}</dd></div><div><dt>Товаров / строк продаж</dt><dd>${state.data.products.length} / ${state.data.sales.length}</dd></div><div><dt>Полнота проверок</dt><dd>${q.score}%</dd></div></dl>${q.issues.length?`<ul class="issue-list">${q.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<div class="success-note">'+icon('check')+' Базовые проверки пройдены. Достоверность источника подтверждает фермер.</div>'}<div class="button-row">${btn('Импорт JSON / CSV','import','primary')}${btn('Шаблон CSV','template-csv')}${btn('Сменить демо-сценарий','scenario')}</div><p class="fine-print">JSON: до 5 МБ, 500 товаров, 20 000 строк продаж. CSV обновляет товары; история остаётся для совпадающих ID. Перед применением всегда есть предпросмотр.</p></section><section class="panel integrations"><h2>Подключение к вашей работе</h2>${[['Магазин и учёт','Товары, остатки, сроки, продажи'],['CRM / клиентская база','Только агрегаты и количество согласий'],['Площадка продаж','Черновик → подтверждение → отдельная отправка']].map(([t,s])=>`<div class="integration-row"><span class="mini-icon">${icon('box')}</span><span><b>${t}</b><small>${s}</small></span>${badge('План','soft')}</div>`).join('')}<p>Внешние сервисы сейчас не подключены. Работают импорт файлов и локальные сценарии.</p>${btn('Открыть план интеграции','integration','secondary')}</section></div><section class="panel rules-preview"><div class="panel-head"><div><p class="eyebrow">НИКАКОГО ЧЁРНОГО ЯЩИКА</p><h2>Почему одно действие важнее другого</h2></div>${btn('Все правила и допущения','rules')}</div><div class="weights"><div><strong>45%</strong><span>Нижняя оценка эффекта</span></div><div><strong>30%</strong><span>Срочность</span></div><div><strong>15%</strong><span>Надёжность данных</span></div><div><strong>10%</strong><span>Простота выполнения</span></div></div><p class="fine-print">Эффект нормируется логарифмически. Смена фокуса добавляет небольшой бонус. Версия правил ${VERSION}; оценка надёжности не является вероятностью успеха.</p></section><section class="bottom-grid"><div class="panel"><h2>Безопасность MVP</h2><div class="check-note">${icon('shield')} Данные остаются в браузере. Серверных записей и ключей нет.</div><div class="check-note">${icon('shield')} Произвольные скрипты и внешние соединения ограничены CSP.</div><div class="check-note">${icon('shield')} Каталог не зашифрован приложением. Экспортируйте копию и берегите доступ к устройству.</div>${btn('Экспортировать журнал','export-history')}</div><div class="panel"><h2>Что добавить после пилота</h2><p>SSO и роли, серверная история и согласия, реальные коннекторы, журнал аудита, измерение эффектов с контрольными группами.</p><p>Локальные Qwen 0.5B и 1.5B объясняют данные и готовят тексты в разделе ИИ-помощника. Расчёты, приоритет и разрешение на действие остаются в проверяемом коде.</p>${btn('Исследование и источники','research')}${btn('Все возможности и следующие функции','feature-map')}</div></section>`;}
function open(content,wide=false){dialog.className=wide?'wide-dialog':'';dialog.innerHTML=`<button class="close-dialog icon-btn" data-act="close" aria-label="Закрыть">${icon('close')}</button>${content}`;if(!dialog.open)dialog.showModal();dialog.querySelector('h2')?.setAttribute('tabindex','-1');dialog.querySelector('h2')?.focus();}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000);}
function download(name,content,type='application/json'){const b=new Blob([content],{type});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function openAction(id){const a=candidates(state.data,{goal:state.goal}).find(a=>a.id===id);if(!a)return toast('Сигнал изменился. Обновите список.');activeAction=a;const p=state.data.products.find(p=>p.id===a.productId);const existing=state.events.some(e=>e.actionId===a.id&&e.day===today()&&['approved','done'].includes(e.status));open(`<p class="eyebrow">ДЕЙСТВИЕ С ОБЪЯСНЕНИЕМ · ${a.score}/100</p><h2 id="dialog-title">${esc(a.title)}</h2><p class="dialog-lead">${esc(a.reason)}</p><div class="effect-box"><span>${a.label} · ${a.horizon} дн.</span><strong>${money(a.low)} – ${money(a.high)}</strong><small>Сценарная оценка, не гарантированный доход</small></div><h3>Как получен диапазон</h3><p>${esc(a.formula)}</p><div class="assumption">${icon('info')}<p>${esc(a.assumption)}</p></div><details><summary>Проверить исходные сигналы</summary><dl class="data-dl"><div><dt>Источник</dt><dd>${esc(state.data.source)}</dd></div><div><dt>Актуальность</dt><dd>${state.data.updatedAt}</dd></div><div><dt>Надёжность данных</dt><dd>${Math.round(a.reliability*100)}/100 (шкала правил)</dd></div><div><dt>Версия правил</dt><dd>${VERSION}</dd></div></dl></details><h3>Что сделать</h3><ol class="action-steps">${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${p?`<button class="text-button" data-edit="${p.id}">Проверить данные товара ${icon('arrow')}</button>`:''}<div class="divider"></div><label class="confirm-label"><input id="action-confirm" type="checkbox" ${existing?'disabled':''}> Я проверил исходные данные, расчёт и хочу подготовить это действие</label><button id="approve-action" class="btn primary full" data-act="approve-action" disabled>${existing?'Уже есть в плане':'Подтвердить и подготовить черновик'} ${icon('arrow')}</button><p class="fine-print">Подтверждается только локальный черновик. Закупка, изменение цены, публикация и рассылка не выполняются.</p><div class="button-row"><button class="btn quiet" data-act="snooze">Вернуться завтра</button><button class="btn quiet" data-act="reject">Мне не подходит</button></div>`);}
function draftText(a){const p=state.data.products.find(p=>p.id===a.productId);return`ЧЕРНОВИК, НЕ ОПУБЛИКОВАНО\n${a.title}\n\nПричина: ${a.reason}\n\nПлан:\n${a.steps.map((x,i)=>(i+1)+'. '+x).join('\n')}\n\nРасчёт: ${a.formula}\nДопущение: ${a.assumption}\n\nИсточник: ${state.data.source}; дата ${state.data.asOf}.\nПодтверждено фермером только в локальном прототипе. Внешние действия отсутствуют.\n${p?'Товар: '+p.id:''}`;}
function editProduct(id){const p=state.data.products.find(p=>p.id===id)||{id:'p-'+Date.now(),name:'',category:'Овощи',unit:'шт',price:100,cost:50,stock:0,expiresIn:7,leadDays:2,photos:0,completeness:0,color:'sage',symbol:'Т'};const existing=state.data.products.some(x=>x.id===id);open(`<p class="eyebrow">АССОРТИМЕНТ · ЛОКАЛЬНО</p><h2 id="dialog-title">${existing?'Проверить товар':'Добавить товар'}</h2><form id="product-form" data-id="${esc(p.id)}"><label class="field">Название<input name="name" value="${esc(p.name)}" maxlength="120" required></label><div class="form-row"><label class="field">Категория<input name="category" value="${esc(p.category)}" required maxlength="120"></label><label class="field">Единица<input name="unit" value="${esc(p.unit)}" required maxlength="12"></label></div><div class="form-row">${[['price','Цена, ₽',.01,1e7],['cost','Себестоимость, ₽',0,1e7],['stock','Остаток',0,1e7],['expiresIn','Дней до конца срока партии',0,3650],['leadDays','Срок поставки, дней',0,365],['photos','Количество фото',0,100],['completeness','Заполненность карточки, %',0,100]].map(([k,l,min,max])=>`<label class="field">${l}<input name="${k}" type="number" min="${min}" max="${max}" step="any" value="${p[k]}" required></label>`).join('')}</div><div class="callout small">История продаж не меняется. Для нового товара её пока нет. Факты о составе и сертификатах не генерируются.</div><label class="confirm-label"><input name="confirmed" type="checkbox" required> Я проверил данные и хочу сохранить их локально</label><button class="btn primary full" type="submit">Подтвердить изменения</button></form>`);}
function segmentMessage(id){const s=state.data.segments.find(s=>s.id===id);if(!s)return;open(`<p class="eyebrow">ЧЕРНОВИК СООБЩЕНИЯ</p><h2 id="dialog-title">${esc(s.name)}</h2><p>Сегмент: ${s.count} покупателей. Согласия в источнике: ${s.consented}. Адресаты в MVP не загружаются.</p><label class="field">Тон<select id="message-tone"><option value="warm">Тёплый</option><option value="short">Короткий</option><option value="business">Нейтральный</option></select></label><label class="field">Текст<textarea id="message-text" rows="5">Здравствуйте! На связи ферма «${esc(state.data.farm)}». Если планируете заказ, будем рады помочь выбрать продукты из нашего ассортимента. Напишите, что вам нужно, и мы уточним наличие.</textarea></label><div class="assumption">${icon('info')} Не обещаем наличие, доставку, органический статус или скидку без проверенных данных.</div><label class="confirm-label"><input id="message-confirm" type="checkbox"> Я проверил текст. Согласия адресатов проверю перед отправкой в своей CRM</label><button class="btn primary full" id="copy-message" data-act="copy-message" disabled>Подтвердить и скопировать текст ${icon('copy')}</button><p class="fine-print">В приложении нет отправки сообщений. Текст строится шаблоном, без внешней нейросети.</p>`);}
function rules(){open(`<p class="eyebrow">ПРИОРИТИЗАЦИЯ · ВЕРСИЯ ${VERSION}</p><h2 id="dialog-title">Почему именно эти три</h2><p>Движок ищет сигналы в текущем наборе, рассчитывает сценарный диапазон, оценивает срочность и показывает первые три подходящих действия.</p><div class="formula">45% эффект + 30% срочность<br>+ 15% надёжность + 10% простота</div><p>Эффект: log(1 + нижняя оценка) / log(10001), ограничен от 0 до 1. Простота: 1 − минуты / 60. Фокус «Потери» даёт +10 баллов сохранению партии, «Продажи» +8 карточкам и возврату клиентов. Итог 0–100.</p><div class="table-scroll"><table><thead><tr><th>Сигнал</th><th>Правило</th><th>Ожидаемый результат</th></tr></thead><tbody><tr><td>Партия под риском</td><td>Срок ≤5 дней, запас выше ожидаемых продаж, излишек ≥3</td><td>30–60% излишка × маржа после −15%</td></tr><tr><td>Риск отсутствия</td><td>Запас в днях меньше срока поставки</td><td>50–90% недостающего спроса × маржа</td></tr><tr><td>Слабая карточка</td><td>≥100 просмотров, заполненность &lt;80% или &lt;2 фото</td><td>Прирост конверсии 0,3–0,8 п.п.</td></tr><tr><td>Возврат покупателей</td><td>≥21 дня без заказа, ≥10 согласий</td><td>Отклик 3–8% × средний чек × маржа</td></tr></tbody></table></div><h3>Защита от плохих рекомендаций</h3><p>Не советуем скидку с отрицательной маржой. Не оцениваем спрос при отсутствии продаж. Снижаем надёжность старых данных. Убираем подтверждённые и отклонённые действия на текущую дату. Отложенные возвращаем после выбранного дня.</p><p>Диапазоны отклика и конверсии заданы для MVP, не откалиброваны и не доказывают эффект. Надёжность 0–100 является шкалой правил, не вероятностью успеха.</p><h3>ИИ в этой версии</h3><p>Приоритеты и суммы рассчитывает объяснимый движок правил. Отдельно подключены Qwen 2.5 0.5B и 1.5B через WebLLM для диалога и черновиков. Модель работает на устройстве и не может выполнять действия. Её факты и текст нужно проверять.</p>${btn('Скачать правила в Markdown','download-rules')}`,true);}
function integration(){open(`<p class="eyebrow">ПЛАН ВНЕДРЕНИЯ, НЕ ПОДКЛЮЧЁННЫЕ СЕРВИСЫ</p><h2 id="dialog-title">От файлов к интеграции</h2><ol class="action-steps"><li>Получить обезличенные товары и продажи в режиме чтения. Сопоставить ID, даты, остатки и себестоимость.</li><li>Загрузить только агрегаты сегментов: количество, согласия, чек, давность. Персональные адресаты остаются в CRM.</li><li>Рассчитать рекомендации на сервере с версией правил, снимком данных и сроком актуальности.</li><li>Подготовить черновик. Фермер проверяет параметры и подтверждает конкретную версию.</li><li>Отдельный адаптер выполняет действие в пределах выданных прав; записывает ответ и защищается от повторной отправки.</li></ol><h3>Предлагаемые HTTP-маршруты</h3><pre>POST /api/v1/imports          → проверка набора\nGET  /api/v1/recommendations → три действия\nPOST /api/v1/actions/:id/prepare\nPOST /api/v1/actions/:id/approve\nPOST /api/v1/actions/:id/execute\nGET  /api/v1/audit</pre><p>Эти серверные маршруты в текущем статическом MVP не реализованы. Реально работают загрузка JSON/CSV, редактирование и подтверждения в браузере.</p><h3>Технические условия</h3><p>SSO/OIDC, tenant_id и владение объектами, роли чтения/подтверждения, серверный аудит, idempotency key, revision, истечение подтверждения, HTTPS, секреты в vault. LLM при подключении получает только необходимый обезличенный контекст и не имеет доступа к execute.</p>${btn('Скачать контракт данных','download-schema')}`,true);}
function research(){open(`<p class="eyebrow">ОСНОВАНИЯ И ГИПОТЕЗЫ</p><h2 id="dialog-title">Какие решения фермер принимает регулярно</h2><p>Рабочие гипотезы MVP: какие партии нужно продать раньше, чего не хватит к поставке, где карточка мешает покупке, кому предложить повторный заказ и не уничтожает ли скидка маржу.</p><p>FAO связывает потери продукции с хранением, обработкой, инфраструктурой и доступом к рынку. Это обоснование включить контроль партий, но не доказательство процента эффекта нашей функции.</p><p>Исследования NN/g по карточкам показывают важность информации о товаре, доступности, цене и понятном действии покупки. Они не задают прогноз прироста конверсии для конкретной фермы.</p><h3>Первичные источники</h3><p><a href="https://www.fao.org/platform-food-loss-waste/food-loss/food-loss-reduction/en" target="_blank" rel="noopener noreferrer">FAO: Food loss reduction</a></p><p><a href="https://www.fao.org/cfs/policy-products/voluntary-guidelines-and-policy-recommendations/connecting-smallholders-to-markets" target="_blank" rel="noopener noreferrer">FAO/CFS: Connecting Smallholders to Markets</a></p><p><a href="https://www.nngroup.com/reports/ecommerce-ux-product-pages-including-reviews/" target="_blank" rel="noopener noreferrer">NN/g: Ecommerce UX, Product Pages</a></p><h3>Что исследовать в пилоте</h3><p>5–8 интервью с фермерами, наблюдение утреннего планирования, 2 недели работы на обезличенных выгрузках. Проверять долю полезных рекомендаций, отмены, ошибки исходных данных, время до решения. Для денежного эффекта нужны сопоставимые контрольные группы.</p><p>Интервью в рамках этой сборки не проводились. Целевые числа пилота являются планом, не результатом исследования.</p>`,true);}
function onboarding(){open(`<div class="intro-mark"><img src="./favicon.svg" width="64" height="64" alt=""></div><p class="eyebrow">ДОБРО ПОЖАЛОВАТЬ В РОСТОК</p><h2 id="dialog-title">Ваша ферма.<br>Ваш следующий шаг.</h2><p class="dialog-lead">Начните с учебной фермы, чтобы спокойно пройти весь путь.</p><ol class="action-steps"><li><b>Посмотрите три приоритета.</b> У каждого есть конкретная причина и диапазон эффекта.</li><li><b>Проверьте расчёт.</b> Откройте факты, допущения и план выполнения.</li><li><b>Примите решение.</b> Подтвердите черновик, отложите или отклоните. Ничего не отправляется автоматически.</li></ol><div class="assumption">${icon('shield')} Данные вымышленные. Правила прозрачные. Внешние сервисы не подключены.</div>${btn('Посмотреть мои приоритеты '+icon('arrow'),'start','primary full')}`);}
function afterRender(){if(page==='campaigns'){calcPromo();calcBundle();}if(page==='lab')calcLab();}
function go(p){page=nav.some(x=>x[0]===p)?p:'today';location.hash=page;query='';filter='all';shell();afterRender();document.querySelector('#main').focus();window.scrollTo({top:0,behavior:'instant'});}
function calcPromo(){const p=state.data.products.find(p=>p.id===document.querySelector('#promo-product')?.value);if(!p)return;const c=campaign(p,document.querySelector('#promo-discount').value,document.querySelector('#promo-quantity').value);document.querySelector('#promo-result').innerHTML=`<div class="calc-results ${c.valid?'':'danger'}"><div><span>Новая цена</span><strong>${money(c.price)}</strong></div><div><span>Маржа на единицу</span><strong>${money(c.unitMargin)}</strong></div><div><span>Маржа на ${c.quantity} шт. (не прогноз продаж)</span><strong>${money(c.margin)}</strong></div></div><p class="fine-print">Скидка уменьшит маржу на ${money(c.lostMargin)} при реализации этого количества. ${!c.valid?'Нельзя подтвердить: проверьте срок партии, скидку 0–70%, положительную маржу и количество.':''}</p>`;document.querySelector('#promo-save').disabled=!c.valid||!document.querySelector('#promo-confirm').checked;}
function calcBundle(){const p=state.data.products.find(p=>p.id===document.querySelector('#bundle-one')?.value),q=state.data.products.find(p=>p.id===document.querySelector('#bundle-two')?.value);if(!p||!q)return;const price=Number(document.querySelector('#bundle-price').value),cost=p.cost+q.cost,regular=p.price+q.price,max=p.id===q.id?Math.floor(p.stock/2):Math.min(p.stock,q.stock);const valid=Number.isFinite(price)&&price>cost&&price<1e8&&max>=1&&p.expiresIn>0&&q.expiresIn>0;document.querySelector('#bundle-result').innerHTML=`<div class="calc-results ${valid?'':'danger'}"><div><span>Обычная сумма</span><strong>${money(regular)}</strong></div><div><span>Маржа набора</span><strong>${money(price-cost)}</strong></div><div><span>Можно собрать</span><strong>${max} наб.</strong></div></div><p class="fine-print">Себестоимость двух товаров ${money(cost)}. ${!valid?'Цена должна быть выше себестоимости, а товары в наличии.':'Количество наборов вычислено по текущим остаткам.'}</p>`;document.querySelector('#bundle-save').disabled=!valid||!document.querySelector('#bundle-confirm').checked;}
async function perform(act){
 if(act==='feature-map'){featureCatalogue();return;}if(await extendedAction(act))return;
if(act==='close')return dialog.close();if(act==='menu')return document.body.classList.toggle('menu-open');if(act==='onboarding')return onboarding();if(act==='start'){state.onboarded=true;save();dialog.close();return;}if(act==='rules')return rules();if(act==='integration')return integration();if(act==='research')return research();if(act==='plan')return go('history');
 if(act==='scenario')return open(`<p class="eyebrow">ПЕСОЧНИЦА</p><h2 id="dialog-title">Попробуйте другую ситуацию</h2><p>Сценарий заменит только локальный набор и очистит план. Сначала можно скачать текущие данные и журнал.</p>${[['balanced','Обычная неделя','Есть срочная партия, риск дефицита и слабая карточка.'],['harvest','Большая партия','Больше скоропортящихся товаров и риска списания.'],['quiet','Спокойная неделя','Основные запасы стабильны, на первый план выходят карточки и покупатели.']].map(([id,t,b])=>`<button class="scenario-choice" data-scenario="${id}"><b>${t}</b><span>${b}</span>${icon('arrow')}</button>`).join('')}`);
 if(act==='settings')return open(`<p class="eyebrow">НАСТРОЙКИ</p><h2 id="dialog-title">Ваша ферма</h2><form id="settings-form"><label class="field">Название<input name="farm" value="${esc(state.data.farm)}" required maxlength="120"></label><label class="confirm-label"><input name="reduced" type="checkbox" ${state.compact?'checked':''}> Уменьшить анимации</label><button type="submit" class="btn primary full">Сохранить</button></form><p class="fine-print">Сохраняется локально. Пользователей, серверного аккаунта и внешних подключений здесь нет.</p>`);
 if(act==='search')return open(`<p class="eyebrow">БЫСТРЫЙ ПОИСК</p><h2 id="dialog-title">Что хотите найти?</h2><label class="search-field">${icon('search')}<input id="global-query" placeholder="Товар или действие" autofocus></label><div id="search-results">${searchResults('')}</div>`);
 if(act==='approve-action'){if(!activeAction||!document.querySelector('#action-confirm')?.checked)return;state=approve(state,activeAction,{confirmed:true,day:today()});save();const text=draftText(activeAction);open(`<p class="eyebrow">ПОДТВЕРЖДЕНО ЛОКАЛЬНО</p><h2 id="dialog-title">Черновик в вашем плане</h2><div class="success-note">${icon('check')} Решение записано. Внешние действия не выполнялись.</div><label class="field">План действия<textarea id="draft-text" rows="12" readonly>${esc(text)}</textarea></label><div class="button-row">${btn(icon('copy')+' Скопировать','copy-draft','primary')}${btn(icon('down')+' Скачать TXT','download-draft')}</div>${btn('Открыть план','open-plan','secondary full')}`);shell();return;}
 if(act==='open-plan'){dialog.close();return go('history');}if(act==='copy-draft')return copy(document.querySelector('#draft-text').value);if(act==='download-draft')return download('rostok-action.txt',document.querySelector('#draft-text').value,'text/plain;charset=utf-8');
 if(act==='snooze'){if(!activeAction)return;open(`<p class="eyebrow">ОТЛОЖИТЬ</p><h2 id="dialog-title">Вернуться к действию позже</h2><p>Оно будет скрыто до следующего дня после выбранной даты. Партия может требовать решения раньше.</p><label class="field">Скрыть включительно до<input id="snooze-date" type="date" min="${today()}" value="${today()}"></label>${btn('Подтвердить перенос','confirm-snooze','primary full')}`);return;}
 if(act==='confirm-snooze'){const until=document.querySelector('#snooze-date').value;if(!until||until<today())return toast('Проверьте дату.');state.events.unshift({id:'snooze-'+Date.now(),actionId:activeAction.id,title:activeAction.title,status:'snoozed',day:today(),until,at:new Date().toISOString(),externalExecuted:false});save();dialog.close();shell();toast('Действие отложено. Внешних изменений нет.');return;}
 if(act==='reject')return open(`<p class="eyebrow">ОБРАТНАЯ СВЯЗЬ</p><h2 id="dialog-title">Почему действие не подходит?</h2><label class="field">Причина<select id="reject-reason"><option>Нет возможности выполнить сегодня</option><option>Данные не соответствуют действительности</option><option>Уже сделал в другой системе</option><option>Не вижу пользы для моей фермы</option></select></label>${btn('Подтвердить отклонение','confirm-reject','primary full')}`);
 if(act==='confirm-reject'){state.events.unshift({id:'reject-'+Date.now(),actionId:activeAction.id,title:activeAction.title,status:'rejected',reason:document.querySelector('#reject-reason').value,day:today(),at:new Date().toISOString(),externalExecuted:false});save();dialog.close();shell();toast('Спасибо. Действие убрано из сегодняшних приоритетов.');return;}
 if(act==='copy-message'){if(!document.querySelector('#message-confirm').checked)return;return copy(document.querySelector('#message-text').value);}
 if(act==='add-product')return editProduct(null);
 if(act==='report'){const m=metrics(state.data,null,7),lines=[`РОСТОК · отчёт по ${state.data.demo?'учебным':'импортированным'} данным`,state.data.farm,`Дата: ${state.data.asOf}`,`Выручка 7 дней: ${money(m.revenue)}`,`Валовая маржа: ${money(m.margin)} (по текущей себестоимости, без прочих расходов)`,`Продано единиц: ${m.units}`,'','Приоритеты:',...recommendations(state.data,state).map((a,i)=>`${i+1}. ${a.title}\nПричина: ${a.reason}\nСценарный диапазон: ${money(a.low)}–${money(a.high)}\nДопущение: ${a.assumption}`),'','Диапазоны не суммируются. Внешние действия не выполнялись.'];return download('rostok-weekly-report.txt',lines.join('\n'),'text/plain;charset=utf-8');}
 if(act==='export-data')return download('rostok-data.json',JSON.stringify(state.data,null,2));if(act==='export-history')return download('rostok-audit.json',JSON.stringify({version:VERSION,farm:state.data.farm,events:state.events,notice:'Локальная история, не подтверждение внешних операций.'},null,2));
 if(['export-csv','template-csv'].includes(act))return download('rostok-products.csv',productCSV(state.data),'text/csv;charset=utf-8');
 if(act==='download-schema'){const res=await fetch('./data-contract.json');if(!res.ok)throw Error('Контракт недоступен.');return download('rostok-data-contract.json',await res.text());}
 if(act==='download-rules'){const res=await fetch('./rules.md');if(!res.ok)throw Error('Файл правил недоступен.');return download('rostok-rules.md',await res.text(),'text/markdown;charset=utf-8');}
 if(act==='import'){document.querySelector('#file-input').value='';document.querySelector('#file-input').click();return;}
 if(act==='apply-import'){if(!importDraft||!document.querySelector('#import-confirm')?.checked)return;state.data=importDraft;state.events=[];chat=[];forecastProduct=null;importDraft=null;save();dialog.close();go('today');toast('Данные применены локально. История решений очищена.');return;}
 if(act==='save-promo'){const p=state.data.products.find(p=>p.id===document.querySelector('#promo-product').value),c=campaign(p,document.querySelector('#promo-discount').value,document.querySelector('#promo-quantity').value);if(!c.valid||!document.querySelector('#promo-confirm').checked)return;state.events.unshift({id:'promo-'+Date.now(),actionId:'custom-promo-'+Date.now(),title:`Акция: ${p.name}, ${money(c.price)}, ${c.quantity} шт.`,type:'campaign',status:'approved',day:today(),at:new Date().toISOString(),parameters:c,externalExecuted:false});save();document.querySelector('#promo-confirm').checked=false;calcPromo();toast('Черновик акции подтверждён и добавлен в план. Нигде не опубликован.');return;}
 if(act==='save-bundle'){const p=state.data.products.find(p=>p.id===document.querySelector('#bundle-one').value),q=state.data.products.find(p=>p.id===document.querySelector('#bundle-two').value),price=Number(document.querySelector('#bundle-price').value);if(!document.querySelector('#bundle-confirm').checked||price<=p.cost+q.cost||price>1e8||p.expiresIn<=0||q.expiresIn<=0||(p.id===q.id?p.stock<2:Math.min(p.stock,q.stock)<1))return;state.events.unshift({id:'bundle-'+Date.now(),actionId:'custom-bundle-'+Date.now(),title:`Набор: ${p.name} + ${q.name}`,status:'approved',day:today(),at:new Date().toISOString(),parameters:{price,productIds:[p.id,q.id]},externalExecuted:false});save();document.querySelector('#bundle-confirm').checked=false;calcBundle();toast('Черновик набора в плане. Внешние системы не менялись.');return;}
}
