function searchResults(q){const list=[...state.data.products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())).map(p=>`<button class="search-result" data-edit="${p.id}">${icon('grid')}<span>${esc(p.name)}<small>Товар</small></span>${icon('arrow')}</button>`),...candidates(state.data).filter(a=>a.title.toLowerCase().includes(q.toLowerCase())).map(a=>`<button class="search-result" data-action="${a.id}">${icon('spark')}<span>${esc(a.title)}<small>Рекомендация</small></span>${icon('arrow')}</button>`)];return list.slice(0,10).join('')||'<p class="empty">Ничего не найдено.</p>';}
document.addEventListener('click',async e=>{const target=e.target.closest('button,[data-nav]');if(!target)return;try{if(target.dataset.account){return switchAccount(target.dataset.account);}if(target.dataset.aiTask){const task=TASKS.find(t=>t[0]===target.dataset.aiTask);document.querySelector('#ai-prompt').value=task[2];document.querySelector('#ai-prompt').focus();return;}if(target.dataset.metric){open('<p class="eyebrow">КАК ЭТО СЧИТАЕТСЯ</p><h2 id="dialog-title">Пояснение показателя</h2><p>'+esc(metricHelp[target.dataset.metric])+'</p>');return;}if(target.dataset.copyAnswer){return reviewAI(Number(target.dataset.copyAnswer));}if(target.dataset.nav){dialog.close();document.body.classList.remove('menu-open');return go(target.dataset.nav);}if(target.dataset.act)return await perform(target.dataset.act);if(target.dataset.action)return openAction(target.dataset.action);if(target.dataset.edit)return editProduct(target.dataset.edit);if(target.dataset.segment)return segmentMessage(target.dataset.segment);if(target.dataset.filter){filter=target.dataset.filter;shell();return;}if(target.dataset.scenario){const next=target.dataset.scenario;return open(`<p class="eyebrow">ЗАМЕНИТЬ УЧЕБНЫЙ НАБОР</p><h2 id="dialog-title">Начать выбранный сценарий?</h2><p>Текущий набор и локальная история будут заменены. Это не влияет на скачанные файлы.</p><button class="btn primary full" data-reset-scenario="${next}">Подтверждаю замену набора и истории</button>`);}if(target.dataset.resetScenario){state={...initial(),data:demoProfile(state.profile||'dairy',target.dataset.resetScenario),profile:state.profile||'dairy',onboarded:true};save();dialog.close();go('today');toast('Сценарий готов. Все данные вымышленные.');return;}if(target.dataset.done){const record=state.events.find(x=>x.id===target.dataset.done);open(`<p class="eyebrow">РУЧНАЯ ОТМЕТКА</p><h2 id="dialog-title">Действие выполнено?</h2><p>${esc(record.title)}</p><p>Это ваша отметка. Приложение не проверяет выполнение в других системах.</p><button class="btn primary full" data-confirm-done="${record.id}">Подтверждаю ручное выполнение</button>`);return;}if(target.dataset.confirmDone){const r=state.events.find(x=>x.id===target.dataset.confirmDone);r.status='done';r.completedAt=new Date().toISOString();save();dialog.close();shell();toast('Ручное выполнение отмечено.');return;}if(target.dataset.measure){const r=state.events.find(x=>x.id===target.dataset.measure);return open(`<p class="eyebrow">НАБЛЮДЕНИЕ, НЕ ПРИЧИННЫЙ ЭФФЕКТ</p><h2 id="dialog-title">Какой результат заметили?</h2><form id="measure-form" data-id="${r.id}"><label class="field">Наблюдаемая маржа / экономия, ₽<input type="number" step="any" name="actual" required value="${Number.isFinite(r.actual)?r.actual:''}"></label><label class="field">Как измерили<textarea name="observation" maxlength="500" required>${esc(r.observation||'')}</textarea></label><p>Без контрольного сравнения нельзя приписать весь результат рекомендации.</p><button class="btn primary full" type="submit">Подтвердить наблюдение</button></form>`);}if(target.dataset.remove){const r=state.events.find(x=>x.id===target.dataset.remove);return open(`<p class="eyebrow">ОТМЕНА ЛОКАЛЬНОЙ ЗАПИСИ</p><h2 id="dialog-title">Отменить запись в плане?</h2><p>${esc(r.title)}</p><p>Сигнал может вернуться на главный экран. Внешние операции не отменяются, потому что приложение их не выполняло.</p><button class="btn primary full" data-confirm-remove="${r.id}">Подтвердить отмену записи</button>`);}if(target.dataset.confirmRemove){state.events=state.events.filter(x=>x.id!==target.dataset.confirmRemove);save();dialog.close();shell();toast('Запись отменена.');return;}}catch(err){toast(err.message||'Не удалось выполнить. Проверьте данные.');}});
document.addEventListener('input',e=>{if(['lab-price','lab-demand','lab-expense'].includes(e.target.id))calcLab();if(e.target.id==='global-query')document.querySelector('#search-results').innerHTML=searchResults(e.target.value);if(e.target.id==='catalog-search'){query=e.target.value;const start=e.target.selectionStart;shell();const el=document.querySelector('#catalog-search');el.focus();el.setSelectionRange(start,start);}if(['promo-discount','promo-quantity'].includes(e.target.id)){document.querySelector('#promo-confirm').checked=false;calcPromo();}if(e.target.id==='bundle-price'){document.querySelector('#bundle-confirm').checked=false;calcBundle();}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='insight-period'){insightDays=Number(e.target.value);shell();}if(['forecast-product','forecast-horizon','forecast-method'].includes(id)){forecastProduct=document.querySelector('#forecast-product').value;forecastHorizon=Number(document.querySelector('#forecast-horizon').value);forecastMethod=document.querySelector('#forecast-method').value;shell();}if(id==='lab-product')calcLab();if(id==='goal'){state.goal=e.target.value;save();shell();}if(id==='period'){period=Number(e.target.value);shell();}if(id==='action-confirm')document.querySelector('#approve-action').disabled=!e.target.checked;if(id==='message-confirm')document.querySelector('#copy-message').disabled=!e.target.checked;if(['promo-product','promo-confirm'].includes(id)){if(id==='promo-product')document.querySelector('#promo-confirm').checked=false;calcPromo();}if(['bundle-one','bundle-two','bundle-confirm'].includes(id)){if(id!=='bundle-confirm')document.querySelector('#bundle-confirm').checked=false;calcBundle();}if(id==='import-confirm')document.querySelector('#apply-import').disabled=!e.target.checked;if(id==='message-tone'){const tone=e.target.value,farm=state.data.farm;document.querySelector('#message-text').value=tone==='short'?`Здравствуйте! Это ферма «${farm}». Планируете заказ? Напишите, какие продукты нужны, уточним наличие.`:tone==='business'?`Здравствуйте! Ферма «${farm}» готова помочь с подбором продуктов к следующему заказу. Ответьте на сообщение, чтобы уточнить ассортимент и наличие.`:`Здравствуйте! На связи ферма «${farm}». Если планируете заказ, будем рады помочь выбрать продукты из нашего ассортимента. Напишите, что вам нужно, и мы уточним наличие.`;document.querySelector('#message-confirm').checked=false;document.querySelector('#copy-message').disabled=true;}});
document.addEventListener('input',e=>{if(e.target.id==='message-text'){document.querySelector('#message-confirm').checked=false;document.querySelector('#copy-message').disabled=true;}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='ai-form'){submitAI();return;}try{if(e.target.id==='product-form'){const f=new FormData(e.target);if(!f.get('confirmed'))return;const id=e.target.dataset.id,old=state.data.products.find(p=>p.id===id);const p={id,name:String(f.get('name')).trim(),category:String(f.get('category')).trim(),unit:String(f.get('unit')).trim(),color:old?.color||'sage',symbol:String(f.get('name')).trim().slice(0,1)};for(const k of['price','cost','stock','expiresIn','leadDays','photos','completeness'])p[k]=Number(f.get(k));const products=old?state.data.products.map(x=>x.id===id?p:x):[...state.data.products,p];const validated=validateDataset({...state.data,products});state.data={...validated,demo:state.data.demo,source:state.data.source};save();dialog.close();shell();afterRender();toast('Товар обновлён локально. Рекомендации пересчитаны.');}if(e.target.id==='settings-form'){const f=new FormData(e.target);state.data.farm=String(f.get('farm')).trim();state.compact=Boolean(f.get('reduced'));document.documentElement.dataset.motion=state.compact?'off':'on';save();dialog.close();shell();toast('Настройки сохранены.');}if(e.target.id==='measure-form'){const f=new FormData(e.target),r=state.events.find(x=>x.id===e.target.dataset.id),value=Number(f.get('actual'));if(!Number.isFinite(value)||Math.abs(value)>1e10)throw Error('Проверьте сумму.');r.actual=value;r.observation=String(f.get('observation')).slice(0,500);save();dialog.close();shell();toast('Наблюдение записано отдельно от прогноза.');}}catch(err){toast(err.message);}});
document.querySelector('#file-input').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Файл больше 5 МБ.');const text=await file.text();importDraft=file.name.toLowerCase().endsWith('.csv')?parseProductCSV(text,state.data):validateDataset(JSON.parse(text));open(`<p class="eyebrow">ПРЕДПРОСМОТР ИМПОРТА</p><h2 id="dialog-title">Данные проверены</h2><dl class="data-dl"><div><dt>Товаров</dt><dd>${importDraft.products.length}</dd></div><div><dt>Строк продаж</dt><dd>${importDraft.sales.length}</dd></div><div><dt>Сегментов</dt><dd>${importDraft.segments.length}</dd></div><div><dt>Дата</dt><dd>${importDraft.asOf}</dd></div></dl><p>Набор заменит текущие данные, история решений будет очищена. Файл не отправляется на сервер. Дополнительные неизвестные поля игнорируются.</p><label class="confirm-label"><input id="import-confirm" type="checkbox"> Я использую обезличенные данные и подтверждаю замену набора и истории</label><button id="apply-import" class="btn primary full" data-act="apply-import" disabled>Подтвердить импорт</button>`);}catch(err){importDraft=null;toast('Импорт отменён: '+err.message);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();perform('search');}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(nav.some(x=>x[0]===h)&&h!==page){page=h;shell();afterRender();}});
page=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'today';document.documentElement.dataset.motion=state.compact?'off':'on';shell();afterRender();if(!state.onboarded)onboarding();
function calcLab(){if(!document.querySelector('#lab-product'))return;const price=Number(document.querySelector('#lab-price').value),demand=Number(document.querySelector('#lab-demand').value),expense=Number(document.querySelector('#lab-expense').value),s=simulate(state.data,document.querySelector('#lab-product').value,price,demand,expense);document.querySelector('#lab-price-label').textContent=(price>=0?'+':'')+price+'%';document.querySelector('#lab-demand-label').textContent=(demand>=0?'+':'')+demand+'%';document.querySelector('#lab-result').innerHTML=`<div class="lab-value ${s.delta<0?'negative':''}"><span>Изменение валовой маржи за 7 дней</span><strong>${s.delta>=0?'+':''}${money(s.delta)}</strong></div><div class="waterfall" role="img" aria-label="Базовая маржа ${money(s.base)}, сценарная ${money(s.profit)}"><div><span>Было</span><i style="width:${Math.max(1,s.base/Math.max(Math.abs(s.base),Math.abs(s.profit),1)*100)}%"></i><b>${money(s.base)}</b></div><div><span>Сценарий</span><i style="width:${Math.max(1,Math.abs(s.profit)/Math.max(Math.abs(s.base),Math.abs(s.profit),1)*100)}%;background:${s.profit<0?'#b77f72':'#9c82ac'}"></i><b>${money(s.profit)}</b></div></div><dl><div><dt>Цена в сценарии</dt><dd>${money(s.price)}</dd></div><div><dt>Объём, ограниченный остатком</dt><dd>${s.units.toFixed(1)} ед.</dd></div><div><dt>Выручка</dt><dd>${money(s.revenue)}</dd></div><div><dt>Себестоимость + доп. расходы</dt><dd>${money(s.expenses)}</dd></div><div><dt>Чтобы сохранить прежнюю маржу</dt><dd>${s.breakEven===null?'Нет положительной маржи':s.breakEven+' ед.'}</dd></div></dl>`;}
function aiProgress(){const box=document.querySelector('#llm-status');if(box)box.innerHTML=`<span>${esc(llmStatus.message)}</span><progress value="${llmStatus.progress}" max="1"></progress>`;const form=document.querySelector('#ai-form');if(form){form.querySelector('button[type="submit"]').disabled=!llmStatus.ready||llmStatus.busy;form.querySelector('[data-act="stop-llm"]').disabled=!llmStatus.busy;}const modelSelect=document.querySelector('#llm-model');if(modelSelect)modelSelect.disabled=llmStatus.loading||llmStatus.busy;const load=document.querySelector('[data-act="load-llm"]');if(load)load.disabled=llmStatus.loading||llmStatus.busy;}
async function submitAI(){const input=document.querySelector('#ai-prompt'),prompt=input?.value.trim();if(!prompt)return toast('Напишите вопрос или выберите готовую задачу.');if(llmStatus.busy)return toast('Дождитесь ответа или нажмите «Стоп».');if(!llmStatus.ready)return toast('Сначала загрузите модель.');const history=chat.filter(m=>m.content).slice(-2);chat.push({role:'user',content:prompt});const index=chat.length;chat.push({role:'assistant',content:'',warnings:[]});const host=document.querySelector('#chat-messages');host.innerHTML=chat.map(chatBubble).join('');input.value='';try{const pending=askLLM(state.data,prompt,history,full=>{chat[index].content=full;const text=document.querySelector('#chat-text-'+index);if(text){text.textContent=full;host.scrollTop=host.scrollHeight;}});aiProgress();const result=await pending;chat[index].content=result||'Генерация остановлена до появления ответа.';chat[index].warnings=answerWarnings(result,state.data);const current=document.querySelector('#chat-messages');if(current)current.innerHTML=chat.map(chatBubble).join('');}catch(err){chat[index].content='Ответ не создан: '+err.message;toast('Не удалось получить ответ.');const current=document.querySelector('#chat-messages');if(current)current.innerHTML=chat.map(chatBubble).join('');}finally{aiProgress();}}
function reviewAI(index){const message=chat[index];if(!message)return;open(`<p class="eyebrow">ПРОВЕРКА ТЕКСТА</p><h2 id="dialog-title">Скопировать черновик LLM</h2><label class="field">Отредактируйте перед использованием<textarea id="ai-review-text" rows="9">${esc(message.content)}</textarea></label><label class="confirm-label"><input id="ai-review-confirm" type="checkbox"> Я проверил факты, числа и обещания</label><button class="btn primary full" data-act="copy-ai-reviewed">Подтвердить и скопировать</button>`);}
async function switchAccount(id){if(llmStatus.busy||llmStatus.loading)return toast('Дождитесь загрузки или остановите ответ перед сменой хозяйства.');if(!PROFILES.some(p=>p.id===id))return;accounts[state.profile||'dairy']={...state};try{localStorage.setItem('rostok-accounts-v1',JSON.stringify(accounts));}catch{toast('Не удалось сохранить предыдущий аккаунт. Сначала экспортируйте данные.');return;}const cached=accounts[id];try{state=cached?{...initial(),...cached,data:validateDataset(cached.data),profile:id}:{...initial(),data:demoProfile(id),profile:id,onboarded:true};}catch{state={...initial(),data:demoProfile(id),profile:id,onboarded:true};}chat=[];forecastProduct=null;save();dialog.close();go('today');toast('Открыто демо-хозяйство «'+state.data.farm+'». Данные и план раздельные.');}
async function extendedAction(act){if(act==='accounts'){if(llmStatus.busy||llmStatus.loading){toast('Дождитесь загрузки или остановите генерацию перед сменой хозяйства.');return true;}open(`<p class="eyebrow">ДЕМО-АККАУНТЫ</p><h2 id="dialog-title">Четыре разных хозяйства</h2><p>Это учебные рабочие пространства, не реальные учётные записи. У каждого свой ассортимент, продажи и локальный план. При переключении изменения сохраняются.</p><div class="account-grid">${PROFILES.map(p=>`<button class="account-card ${p.id===state.profile?'selected':''}" data-account="${p.id}"><span style="background:${p.color}">${p.initials}</span><b>${p.name}</b><small>${p.type}</small><p>${p.caption}</p><i>${p.id===state.profile?'Открыто сейчас':'Открыть хозяйство ↗'}</i></button>`).join('')}</div>`,true);return true;}
 if(act==='load-llm'){try{const key=document.querySelector('#llm-model').value;await loadLLM(key,aiProgress);toast('Модель готова на этом устройстве.');}catch(err){llmStatus.message=err.message;aiProgress();toast(err.message);}return true;}
 if(act==='stop-llm'){stopLLM();toast('Останавливаем генерацию.');return true;}
 if(act==='copy-ai-reviewed'){if(!document.querySelector('#ai-review-confirm').checked){toast('Сначала подтвердите проверку текста.');return true;}await copy(document.querySelector('#ai-review-text').value);return true;}
 if(act==='explain-abc'){open('<p class="eyebrow">ПРОСТОЕ ПОЯСНЕНИЕ</p><h2 id="dialog-title">Какие товары делают основную выручку</h2><p>Сортируем товары по выручке. Первые, до накопленной доли 80%, относятся к A. Следующие до 95% к B. Остальные к C. Товар, пересекающий границу, остаётся в начавшейся группе.</p><p>Это способ распределить внимание, а не совет убрать C. Небольшой товар может удерживать покупателя или дополнять набор. Выручка не равна прибыли.</p>');return true;}
 if(act==='forecast-help'){open('<p class="eyebrow">КАК ЧИТАТЬ ПРОГНОЗ</p><h2 id="dialog-title">Сценарий, а не обещание</h2><p>Берём средний темп последней недели и немного учитываем такой же день недели в прошлом. Прогноз последовательно проверяем на последних семи днях, используя только более раннюю историю.</p><p>MAE показывает, на сколько единиц в среднем ошибались за день. WAPE сравнивает суммарную ошибку с фактическим количеством. Чем меньше, тем точнее было на этом коротком отрезке. Это не гарантия будущей точности.</p><p>Полоса расширяется с горизонтом по эвристике. Это не статистический доверительный интервал. Пропущенные в исходнике дни считаются нулевыми продажами. Если это отсутствие данных, сначала исправьте выгрузку.</p>');return true;}
 if(act==='lab-reset'){document.querySelector('#lab-price').value='0';document.querySelector('#lab-demand').value='0';document.querySelector('#lab-expense').value='0';calcLab();return true;}return false;}
// Capability catalogue keeps future work distinct from available interactions.
